PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE app_metadata (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE movies (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  title TEXT,
  description TEXT,
  url TEXT,
  location_id TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE pictures (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  title TEXT,
  description TEXT,
  url TEXT,
  location_id TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE master_locations (   location_id INTEGER PRIMARY KEY AUTOINCREMENT,   location_name TEXT,   location_outinside TEXT,   location_division TEXT,   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP , image_url1 TEXT, image_url2 TEXT);
CREATE TABLE boardgames (   id INTEGER PRIMARY KEY AUTOINCREMENT,   boardgame_name TEXT,   owner_name TEXT,   people_min INTEGER,   people_max INTEGER,   need_time INTEGER,   url_str TEXT,   how_to_play TEXT,   remarks TEXT,   created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP , image_url1 TEXT, image_url2 TEXT);
CREATE TABLE notices (   id INTEGER PRIMARY KEY AUTOINCREMENT,   title TEXT,   station TEXT,   location_id INTEGER,   people INTEGER,   people_name TEXT,   remarks TEXT,   public_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   closed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP , start_hour TEXT, end_hour TEXT, money INTEGER, dateandtime TEXT);
CREATE TABLE users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  username TEXT NOT NULL UNIQUE,
  password TEXT NOT NULL,
  email TEXT NOT NULL,
  role TEXT NOT NULL
);
CREATE TABLE endpoint_authority_mapping (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  url TEXT,
  method TEXT,
  menu_function_id INTEGER NOT NULL,
  required_level INTEGER NOT NULL,
  created_at TEXT,
  updated_at TEXT
);
CREATE TABLE user_role_permissions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  resource TEXT NOT NULL,
  permission_level INTEGER NOT NULL,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE master_menu_function (
  id INTEGER PRIMARY KEY,
  name TEXT
);
CREATE TABLE report_master (
  report_id TEXT PRIMARY KEY,
  report_name TEXT NOT NULL,
  template_file TEXT NOT NULL,
  output_format INTEGER NOT NULL,
  description TEXT,
  updated_at TEXT NOT NULL,
  updated_by TEXT NOT NULL
);
CREATE TABLE report_layout (
  report_id TEXT NOT NULL,
  column_id TEXT NOT NULL,
  column_name TEXT NOT NULL,
  display_label TEXT NOT NULL,
  data_type INTEGER NOT NULL,
  display_order INTEGER NOT NULL,
  visible_flag INTEGER NOT NULL,
  format_pattern TEXT,
  required_flag INTEGER NOT NULL,
  default_value TEXT,
  remarks TEXT,
  updated_at TEXT NOT NULL,
  updated_by TEXT NOT NULL,
  PRIMARY KEY (report_id, column_id),
  FOREIGN KEY (report_id)
    REFERENCES report_master (report_id)
    ON DELETE CASCADE
);
CREATE TABLE settings (
  item TEXT PRIMARY KEY,
  type TEXT NOT NULL,
  val TEXT NOT NULL
);
CREATE TABLE mail_templates (
  locale TEXT NOT NULL,
  template_name TEXT NOT NULL,
  subject TEXT NOT NULL,
  body TEXT NOT NULL,
  PRIMARY KEY (locale, template_name)
);
CREATE TABLE error_codes (
  code TEXT NOT NULL,
  locale TEXT NOT NULL,
  message TEXT NOT NULL,
  PRIMARY KEY (code, locale)
);
CREATE TABLE notify_queue (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  event_type TEXT NOT NULL,
  ref_id INTEGER,
  notified INTEGER DEFAULT 0,
  retry_count INTEGER DEFAULT 0,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  last_attempted_at TEXT
);
CREATE TABLE auth_refresh_token (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  token_hash TEXT NOT NULL UNIQUE,
  expires_at TEXT NOT NULL,
  revoked_at TEXT,
  user_agent TEXT,
  ip_address TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE mypage (   user_id INTEGER PRIMARY KEY,   user_name TEXT NOT NULL,   user_name_jpn TEXT,   jersey_number, INTEGER,   enthusiasm TEXT,   hope_style TEXT,   remarks TEXT,   image_url TEXT,   create_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,   update_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP );
DELETE FROM sqlite_sequence;
CREATE INDEX idx_auth_refresh_token_user_id
ON auth_refresh_token (user_id);
CREATE INDEX idx_auth_refresh_token_expires_at
ON auth_refresh_token (expires_at);
